params.content:
{
  "name": "facturas-proveedores-igic",
  "version": "1.0.0",
  "private": true,
  "description": "Gestor de facturas de proveedores: lee fotos y PDF, crea la base de proveedores y controla lo pagado, lo pendiente y el IGIC.",
  "type": "module",
  "scripts": {
    "build": "node tools/build.mjs",
    "build:windows": "build.bat"
  }
}

// Copia la carpeta `site` a `dist`. El sitio no necesita compilación:
// son ficheros estáticos tal cual, listos para servir.
import { cp, mkdir, rm, readdir } from "node:fs/promises";
import { existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..");
const src = join(root, "site");
const out = join(root, "dist");

if (!existsSync(src)) {
  console.error("No encuentro la carpeta site/ con el sitio.");
  process.exit(1);
}

await rm(out, { recursive: true, force: true });
await mkdir(out, { recursive: true });
await cp(src, out, { recursive: true });

const entries = await readdir(out);
console.log("Sitio copiado a dist/:", entries.join(", "));

@echo off
REM Compila el sitio sin necesidad de Node: copia site\ a dist\
cd /d "%~dp0"
if exist dist rmdir /s /q dist
xcopy site dist /E /I /Y >nul
if errorlevel 1 (
  echo No se pudo copiar el sitio a dist.
  exit /b 1
)
echo Sitio copiado a dist\

/*
 * Arranque: enrutador por hash, eventos globales y avisos iniciales.
 */

import { getState, save, subscribe } from "./store.js";
import { escapeKeyCloses, toast } from "./dom.js";
import * as views from "./views.js";

const ROUTES = ["resumen", "facturas", "proveedores", "importar"];

function routeFromHash() {
  const raw = String(location.hash || "").replace(/^#\/?/, "").split("?")[0];
  return ROUTES.includes(raw) ? raw : "resumen";
}

function storageWorks() {
  try {
    const key = "__probe__";
    localStorage.setItem(key, "1");
    localStorage.removeItem(key);
    return true;
  } catch (_) {
    return false;
  }
}

function boot() {
  views.ui.route = routeFromHash();
  views.render();
  escapeKeyCloses();
  views.wireDropzone();

  window.addEventListener("hashchange", () => {
    views.ui.route = routeFromHash();
    window.scrollTo({ top: 0, behavior: "instant" in window ? "instant" : "auto" });
    views.render();
  });

  document.addEventListener("click", (ev) => {
    if (!(ev.target instanceof Element)) return;

    const actionEl = ev.target.closest("[data-action]");
    if (actionEl) {
      ev.preventDefault();
      views.onAction(actionEl.dataset.action, actionEl);
      return;
    }

    const filterBtn = ev.target.closest("[data-filter-status]");
    if (filterBtn) {
      ev.preventDefault();
      views.onFilterButton(filterBtn);
    }
  });

  document.addEventListener("input", views.onInput);
  document.addEventListener("change", views.onChange);

  const filePicker = document.getElementById("filePicker");
  if (filePicker) {
    filePicker.addEventListener("change", () => {
      if (filePicker.files && filePicker.files.length) views.queueFiles(filePicker.files);
      filePicker.value = "";
    });
  }

  const cameraPicker = document.getElementById("cameraPicker");
  if (cameraPicker) {
    cameraPicker.addEventListener("change", () => {
      if (cameraPicker.files && cameraPicker.files.length) views.queueFiles(cameraPicker.files);
      cameraPicker.value = "";
    });
  }

  // Cualquier cambio en los datos vuelve a pintar la pantalla.
  subscribe(() => views.render());

  if (!storageWorks()) {
    setTimeout(
      () =>
        toast(
          "Este navegador no me deja guardar datos (¿ventana privada?). Puedes usarlo, pero al cerrar se perderá todo.",
          "bad",
          9000
        ),
      900
    );
  }

  const state = getState();
  if (!state.invoices.length && !state.suppliers.length) {
    // Primer arranque: nada que decir, la pantalla ya explica qué hacer.
    console.info("Listo. Sube una factura para empezar.");
  }

  save();
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", boot, { once: true });
} else {
  boot();
}

