REM Compila el sitio sin necesidad de Node.
REM Copia la fuente (site\) a dist\, que es lo que se publica, y deja tambien
REM el sitio servible en la raiz de app\ (index.html + assets\).
cd /d "%~dp0"

if not exist "site\index.html" (
