rem --- 2. El sitio en la raiz de app\ ---------------------------------------
xcopy "site\index.html" . /Y >nul
if errorlevel 1 (
  echo No se pudo copiar index.html a la raiz de app\.
  exit /b 1
)
xcopy "site\assets" "assets" /E /I /Y >nul
if errorlevel 1 (
  echo No se pudieron copiar los assets a la raiz de app\.
  exit /b 1
)

