/** Lo que se ve mientras se abre la base de datos. */
export function renderLoading() {
  const view = document.getElementById("view");
  if (!view) return;
  const meta = pageMeta(ROUTES.includes(ui.route) ? ui.route : "resumen");
  const title = document.getElementById("viewTitle");
  const sub = document.getElementById("viewSub");
  if (title) title.textContent = meta.title;
  if (sub) sub.textContent = meta.sub;
  view.innerHTML = `<section class="card"><div class="empty">
    <div class="spinner" style="margin:0 auto 14px"></div>
    <h3>Abriendo tu base de datos</h3>
    <p>Un momento: preparo las tablas de proveedores y facturas.</p>
  </div></section>`;
}

export function render() {

async function pdfScanCanvases(file, maxPages = 2) {
  const pdfjs = await getPdfjs();
  const data = new Uint8Array(await file.arrayBuffer());
  const doc = await pdfjs.getDocument({ data, isEvalSupported: false }).promise;
  const pages = Math.min(doc.numPages, maxPages);
  const out = [];
  for (let p = 1; p <= pages; p++) {
    const page = await doc.getPage(p);
    const base = page.getViewport({ scale: 1 });
    // Más resolución que antes: el texto pequeño de una factura sale más nítido.
    const targetWidth = 2100;
    const scale = Math.min(3.6, Math.max(1.2, targetWidth / base.width));
    const viewport = page.getViewport({ scale });
    const canvas = document.createElement("canvas");
    canvas.width = Math.round(viewport.width);
    canvas.height = Math.round(viewport.height);
    const ctx = canvas.getContext("2d", { willReadFrequently: true });
    ctx.fillStyle = "#fff";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    await page.render({ canvasContext: ctx, viewport }).promise;
    out.push(canvas);
  }
  try {
    doc.destroy();
  } catch (_) {
    /* nada */
  }
  return out;
}

