    // El enlace «Saltar al contenido» usa #view: no es una sección, no se repinta.
    if (location.hash && !location.hash.startsWith("#/")) return;
    views.ui.route = routeFromHash();
    window.scrollTo(0, 0);
    if (!dbReady) {
      views.renderLoading();
      return;
    }
    views.render();
  });

